const fs = require("fs");
const envText = fs.readFileSync(".run.local.env", "utf8");
for (const line of envText.split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m) process.env[m[1]] = m[2].replace(/^["\x27]|["\x27]$/g, "");
}
require("ts-node/register/transpile-only");
const mongoose = require("mongoose");
const { Pool } = require("pg");
const TransHisModel = require("./models/trans-his/trans-his.model");
const TransHisPgModel = require("./models/trans-his-pg/trans-his-pg.model");
const { compileFilter } = require("./models/trans-his-pg/trans-his-pg.query");
const CollectionPure = require("./logics/export/trans-his/trans-his-collection-export.pure");
const InternalPure = require("./logics/export/trans-his/internal-transfer-export.pure");

const logger = { info() {}, warn() {}, error() {}, debug() {} };

(async () => {
  const conn = await mongoose.createConnection(process.env.TRANS_HIS_MONGO_URI).asPromise();
  const mongoModel = new TransHisModel(conn);
  const pool = new Pool({
    host: process.env.TRANS_HIS_PG_HOST,
    port: Number(process.env.TRANS_HIS_PG_PORT),
    user: process.env.TRANS_HIS_PG_USER,
    password: process.env.TRANS_HIS_PG_PASS,
    database: process.env.TRANS_HIS_PG_DB,
  });
  const pgModel = new TransHisPgModel(pool, logger);

  const cases = [
    {
      label: "1. User exact URL (TransHisCollectionExport, no transType, sysTrans=true, connector=bidv)",
      pure: CollectionPure,
      params: { connector: "bidv", dateFr: "2026-03-31T17:00:00.000Z", dateTo: "2026-04-30T16:59:59.999Z", sysTrans: "true" }
    },
    {
      label: "2. TransHisCollectionExport + transType=INTERNAL_BANK_TRANSFER + sysTrans=true + connector=bidv",
      pure: CollectionPure,
      params: { connector: "bidv", dateFr: "2026-03-31T17:00:00.000Z", dateTo: "2026-04-30T16:59:59.999Z", sysTrans: "true", transType: "INTERNAL_BANK_TRANSFER" }
    },
    {
      label: "3. TransHisCollectionExport + transType=MERCHANT_PAYMENT + (default sysTrans!=true) + connector=bidv",
      pure: CollectionPure,
      params: { connector: "bidv", dateFr: "2026-03-31T17:00:00.000Z", dateTo: "2026-04-30T16:59:59.999Z", transType: "MERCHANT_PAYMENT" }
    },
    {
      label: "4. InternalTransferExport + sysTrans=true + connector=bidv",
      pure: InternalPure,
      params: { connector: "bidv", dateFr: "2026-03-31T17:00:00.000Z", dateTo: "2026-04-30T16:59:59.999Z", sysTrans: "true" }
    }
  ];

  for (const c of cases) {
    const cfg = c.pure.getConfig(c.params, "vi");
    const filter = cfg.query.filter;
    const vals = [];
    const sqlWhere = compileFilter(filter, vals);
    const [mongoCount, pgCount] = await Promise.all([
      mongoModel.countDocuments(filter),
      pgModel.countDocuments(filter)
    ]);
    console.log("------------------------------------------------------------");
    console.log(c.label);
    console.log("Built Mongo Filter:", JSON.stringify(filter));
    console.log("Compiled PG WHERE:", sqlWhere, "Values:", JSON.stringify(vals));
    console.log("Result -> Mongo count:", mongoCount, "| PG count:", pgCount);
  }

  await pool.end();
  await conn.close();
})().catch(e => { console.error(e); process.exit(1); });
